-- SwiftletCare REFERENCE DATASET v1.0.0 -- LOCKED --
-- Synthetic DEV/TEST fixture. IDs and timestamps are deterministic, NOT production/live values.
-- Run ONLY once after schema / Flyway V1 on a completely empty 17-table database.
-- The DO guard prevents applying it to any non-empty application table.
-- UTC timestamps; 17-23 October 2026 in Asia/Ho_Chi_Minh; snapshots/reports have NULL path.
BEGIN;
DO $$
DECLARE t TEXT; n BIGINT;
BEGIN
  FOREACH t IN ARRAY ARRAY['users','houses','house_memberships','zones','zone_configs','devices','sensors','actuators','telemetry','control_commands','count_logs','anomaly_events','alerts','alert_histories','notification_deliveries','reports','harvest_logs'] LOOP
    EXECUTE format('SELECT COUNT(*) FROM %I', t) INTO n;
    IF n <> 0 THEN RAISE EXCEPTION 'BASELINE V1 requires empty % table; found % rows. Aborting without changes.',t,n; END IF;
  END LOOP;
END;
$$;

